<script setup>import{ref}from'vue';import FigmaTag from './FigmaTag.vue';import FigmaPersonListPopup from './FigmaPersonListPopup.vue';defineProps({items:{type:Array,default:()=>[]},people:{type:Array,default:()=>[]}});defineEmits(['more']);const showPeople=ref(false);</script>
